CREATE OR REPLACE FUNCTION calculate_delivery_score(p_carrier_id INT, p_quarter_year TEXT)
RETURNS NUMERIC AS $$
DECLARE
  v_on_time INT;
  v_total INT;
  v_score NUMERIC;
BEGIN
  SELECT 
    COUNT(*) FILTER (WHERE actual_delivery_date IS NOT NULL AND actual_delivery_date <= scheduled_delivery_date),
    COUNT(*)
  INTO v_on_time, v_total
  FROM shipments
  WHERE carrier_id = p_carrier_id
    AND 'Q' || EXTRACT(QUARTER FROM scheduled_delivery_date) || '-' || EXTRACT(YEAR FROM scheduled_delivery_date) = p_quarter_year;

  IF v_total = 0 THEN
    RETURN 0.00;
  END IF;

  v_score := ROUND((v_on_time * 100.0) / v_total, 2);
  RETURN v_score;
END;
$$ LANGUAGE plpgsql;

SELECT calculate_delivery_score(101, 'Q1-2024') AS result;
